from collections import deque
from typing import Iterable, List, Set, Tuple


def critical_roads(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str]]:
    """
    Find the roads whose closure would cut a region in two.

    Roads are undirected and the network is built with ``build_adjacency``. A road
    between depots ``a`` and ``b`` is critical if, once it is closed, ``b`` can no
    longer be reached from ``a``. Self-loops are never critical. Networks are small (a
    few dozen roads), so checking each road separately is fine.

    Returns the critical roads as ``(code_a, code_b)`` pairs with ``code_a < code_b``,
    sorted, each road listed once.

    Example:
        critical_roads([("A", "B", 1), ("B", "C", 1), ("C", "A", 1), ("C", "D", 4)]) == [("C", "D")]
    """
    # Collect unique undirected edge pairs (ignoring self-loops and duplicate roads).
    pairs: Set[Tuple[str, str]] = set()
    nodes: Set[str] = set()
    for a, b, _km in edges:
        nodes.add(a)
        nodes.add(b)
        if a == b:
            continue
        if a < b:
            pairs.add((a, b))
        else:
            pairs.add((b, a))

    # Build an undirected adjacency set from the unique pairs.
    adj: dict = {n: set() for n in nodes}
    for a, b in pairs:
        adj[a].add(b)
        adj[b].add(a)

    critical: List[Tuple[str, str]] = []
    for a, b in pairs:
        # Check whether b is reachable from a with the (a, b) road closed.
        blocked = {a, b}
        visited: Set[str] = {a}
        queue = deque([a])
        while queue:
            cur = queue.popleft()
            for nb in adj[cur]:
                if nb in visited:
                    continue
                # A neighbour is reachable only if the road (cur, nb) is not the blocked one.
                if {cur, nb} == blocked:
                    continue
                visited.add(nb)
                queue.append(nb)
        if b not in visited:
            critical.append((a, b))

    return sorted(critical)
